// `npm run gen:edge-kernels`. Imported by bridge-weekly-sheet, customer-portal, drive-link, gc-trade-portal, gmail-count, gmail-sync, messages-email, messages-notify, messages-nudge-dispatch, photo-save, quo-send, quo-webhook, send-estimate-to-customer, walk (the schedule's PR 14b).
/**
 * Messages, cut 1 (the spine): what a contact is called, split from `kernel.ts` (which re-exports it) so the Quo edge
 * functions can name a line by the same rule. Nothing here imports, so the edge copy (`scripts/edge-kernels.mjs`) holds
 * it whole. Lifted from the Messages prototype v1.178 (`firstName`, `initials`, `kindWord`).
 */

export type ContactKind = 'customer' | 'trade' | 'arch' | 'lead' | 'supply_house' | 'candidate' | 'sub' | 'team' | 'unknown'

const TITLE = /^(Dr|Mr|Mrs|Ms)\.?$/i

/**
 * What a greeting calls a full name: the first name, or a title with the last name ("Dr. Priya Raman" is "Dr. Raman",
 * the Board's rule). '' for no name. Owner Billing's `customerGreeting` reads the same rule.
 */
export function greetingName(fullName: string): string {
  const words = fullName.trim().split(/\s+/).filter(Boolean)
  if (words.length === 0) return ''
  const titled = words.length > 1 && TITLE.test(words[0]!)
  // A company's record name reads "Structura, Inc."; its first word keeps no comma, or the greeting reads "Structura,,".
  const word = (w: string) => w.replace(/[,;:]+$/, '')
  return titled ? `${words[0]} ${word(words[words.length - 1]!)}` : word(words[0]!)
}

/**
 * What we call them, in a greeting and in a sentence: what they go by, else `greetingName`, so a title on the record is
 * never dropped. '' for a number nobody has named; a sentence says "they" there.
 */
export function firstName(c: { name: string; goesBy?: string | null; kind?: ContactKind }): string {
  const goesBy = c.goesBy?.trim()
  if (goesBy) return goesBy
  if (c.kind === 'unknown') return ''
  return greetingName(c.name)
}

/** The face's two letters, a title skipped: "PR" for Dr. Priya Raman. "?" for a number nobody has named. */
export function initials(c: { name: string; kind?: ContactKind }): string {
  if (c.kind === 'unknown') return '?'
  return c.name
    .split(/\s+/)
    .filter((w) => w && !TITLE.test(w))
    .map((w) => w[0]!)
    .slice(0, 2)
    .join('')
    .toUpperCase()
}

const KIND_WORD: Record<ContactKind, string> = {
  customer: 'customer',
  trade: 'trade partner',
  arch: 'architect',
  lead: 'lead',
  supply_house: 'supply house',
  candidate: 'candidate',
  sub: 'sub',
  team: 'teammate',
  unknown: 'who is this?',
}

/** "trade partner": what they are to us, for the line under a name. */
export function kindWord(kind: ContactKind): string {
  return KIND_WORD[kind]
}

/**
 * The line under a contact nobody has named, where a named one reads what they are to us: the fact, by the way they
 * reached us, so the thread's header asks *Who is this?* once, on its button (v2.5541).
 */
export function unnamedWords(reach: { phones: number; emails: number }): string {
  if (reach.phones > 0) return 'A number nobody has named'
  if (reach.emails > 0) return 'An address nobody has named'
  return 'Nobody has named them'
}

/**
 * The same fact on one line of a lane, by the way that line went (v2.5994, Wendi's finding of 2026-10-27: an email she
 * sent to an address nobody had named read *A number nobody has named* on Went out). An email names an address, a text or
 * a call a number, and a line with no channel reads as a text, the lanes' default.
 */
export function unnamedOnLine(channel: string | null | undefined): string {
  return unnamedWords(channel === 'email' ? { phones: 0, emails: 1 } : { phones: 1, emails: 0 })
}
